import java.util.*;
class QueueModel {record Message(String id,int value){}static class Task{final Message m;final int group;String state="ready";int attempts,due;Task(Message m,int g){this.m=m;group=g;}}record Result(int[] effects,int deliveries,int done,int dead,int pending){}
static Result deliver(List<Message> messages,int groups,int workers,int perWorker,int ticks,int visibility,int retries,boolean deduplicate,boolean loseFirstAck,String failMessage){List<Task> tasks=new ArrayList<>();for(Message m:messages)for(int g=0;g<groups;g++)tasks.add(new Task(m,g));Set<String> inbox=new HashSet<>();int[] effects=new int[groups];boolean lost=false;int deliveries=0;
for(int tick=0;tick<ticks;tick++){for(Task t:tasks)if(t.state.equals("inflight")&&t.due<=tick)t.state=t.attempts>=retries+1?"dead":"ready";for(int group=0;group<groups;group++){int budget=workers*perWorker;for(Task t:tasks){if(budget==0)break;if(t.group!=group||!t.state.equals("ready"))continue;budget--;t.state="inflight";t.due=tick+visibility;t.attempts++;deliveries++;if(t.m.id().equals(failMessage))continue;String key=group+":"+t.m.id();if(!deduplicate||!inbox.contains(key)){effects[group]+=t.m.value();inbox.add(key);}if(loseFirstAck&&!lost)lost=true;else t.state="done";}}}
int done=0,dead=0;for(Task t:tasks){if(t.state.equals("done"))done++;if(t.state.equals("dead"))dead++;}
return new Result(effects,deliveries,done,dead,tasks.size()-done-dead);}}
